#define PI 3.141592654
#define STEP(x) smoothstep(0.,-.01,x)
vec3 rotateX(vec3 pos, float angle) {
    float c = cos(angle), s = sin(angle);
    return vec3(pos.x, mat2(c,-s,s,c)*pos.yz);
}
vec3 rotate(vec3 pos, float phi, float theta) {
    return rotateX(rotateX(pos, theta).yzx, phi).zxy;
}
vec3 eye(vec2 uv, float phi, float theta, float sgn, float p) {
    float uv_r = length(uv);
    if (uv_r >= 1.)return vec3(1,.95,.93); // extended skin
    vec3 pos = rotate(vec3(uv, sqrt(1.0-dot(uv,uv))), phi, theta);
    float sin_t = length(pos.xy),
    theta2 = atan(sin_t, pos.z) * 1.4,
    phi2 = mod(atan(pos.x, pos.y)+1.5-PI, 2.0*PI)-PI,
    l = sqrt(2.+sin(phi2*37.+4.*theta2) - sin(phi2*17.-4.*theta2)),
    f = sin(15.*iTime)*.0025*(5.+phi2),
    t = clamp(4.*(.9-theta2-.02*cos(phi2*4.)),0.,1.);
    vec3 iris = l * vec3(.3,.4,.7),
    c = mix(vec3(1.0) * (t>0.?min(max(1.-7.*t, 0.)+t*.5, 1.) : 1.), iris, t);
    c = mix(c, vec3(0.0), clamp(10.*(0.45+p+ f*f*5.5 - theta2),0.,1.));
    c *= 1.- t*.6*smoothstep(.2, 0., (sin(phi2)+1.) - (.2+theta2));
    return c+max(2.-10.*length(vec2(2.*(abs(theta2-.4)-.1+f), abs(abs(phi2)-1.7+f)-.7)),0.);
}
float sqr(float x) {
    return x*x;
}
vec3 sqr(vec3 x) {
    return x*x;
}
float sigmoid(float x) {
    return 2.0 / (1.0 + exp(2. - 4. * x)) - 1.0;
}
#define THICK(x,mid,width,maxi) maxi*(1.0-sqr(sqr(2.0*(x-mid)/width)))
vec2 lashes(vec2 uv, float mx) {
    uv.y -= .1 * exp(-sqr(uv.x - mx) / .4) - .05;
    float s = uv.x * uv.x, f2 = .25 - s,
    v2 = STEP(abs(f2 - uv.y)-THICK(uv.x, -.1, .4, .023));
    vec3 f = vec3(.95, .55, 0.4) * (uv.x * s - vec3(.5, 1.1, 1.6)) * s,
    v = STEP(abs(f - uv.y)-THICK(uv.x, vec3(.1,.2,.3), vec3(1.4, 1.6, 1.6), .1));
    return vec2(max(max(v.x, v2), max(v.y, v.z)), STEP(.05-f.z+uv.y));
}
vec2 lower_eyelid(vec2 uv) {
    float s = uv.x * uv.x,
    f = .8 * (.3 * sqr(s) + .2 * s),
    t = .2 * max(0., .06 - uv.x*uv.x - 1.5*uv.x*uv.x*uv.x),
    v = STEP(2.*(abs(f - uv.y)-t));
    return vec2(v, STEP(f - uv.y + t));
}
vec3 full_eye(vec2 uv, vec2 m, float sgn) {
    vec2 u = lashes(uv*vec2(-.6,.7-min(0.,m.y))+vec2(.1,-.4-min(.25,m.y)),-m.x),
    l = lower_eyelid((uv+vec2(-.1,.7-clamp(m.y,-.2,.25)))*vec2(.8,.4-.2*min(.25,m.y)));
    float eye_hole = min(u.y, l.y);
    vec3 eye_col = eye(uv * vec2(1.1,1), PI-m.x, PI-m.y, sgn, -m.y*.1),
    skin = mix(vec3(1.,.95,.93), vec3(.3,.2,.2), max(u.x, l.x*u.y));
    // eye shadow
    skin -= .3*STEP(.4*abs(-.4-uv.y+m.y*.6-(.4-.2*m.y)*(1.-(uv.x-.1)*uv.x)) - .04*max(0.,-m.y)*sqrt(max(0.,1.-2.*abs(uv.x-.2))));
    // eyebrow
    float x = max(0., (1.4 - uv.x) * 5.),
    curve = (.2+.1*m.y)*sqrt(x+.3)*(1.2-x*x*.005) + .2*exp(-sqr(uv.x-1.-4.*m.x)/2.) - .05,
    t = max(0., x/(1.+x) - .07*x);
    skin -= .5*STEP(.4*(abs(-.8+uv.y-curve-max(m.y,0.))-.15*sqrt(t)));
    return mix(skin, eye_col, eye_hole);
}
float mustache(vec2 x) {
    float z = abs(x.x), a = x.y-.3*sqrt(z/(2.-z))*sqr(z-1.7), b = sqr(z-1.)+3.*sqr(x.y)-1.;
    return STEP(a)*STEP(b);
}
float nose(vec2 x) {
    return STEP(5.*sqr(x.y-.4*abs(x.x)+.25)+sqr(abs(x.x)-0.4)-.04+x.x*.03);
}
vec3 face(vec2 uv, vec2 m) {
    vec3 c = full_eye(vec2(2.0 - abs(uv.x*2.0), uv.y*2.0-.2), vec2(0.1-sign(uv.x)*m.x, m.y), sign(uv.x));
    float mask = 1.0 + smoothstep(4., 0.5, 0.3*sqr(sqr(uv.x))-0.9*sqr(uv.x)*(1.-0.5*uv.y)+2.*sqr(uv.y-0.2));
    c = mix(c, vec3(.5, .4, .4), nose(uv/.3+vec2(0,2.9-.4*m.y)));
    c *= mask * 0.5;
    c = mix(c, vec3(.35, .2, .2), mustache(uv/.7+vec2(0,1.7-.3*m.y+.2*m.x*uv.x)));
    return c;
}
#define R iResolution
void mainImage(out vec4 O, vec2 C) {
    vec2 uv = (C-R.xy*0.5)/min(R.x, R.y) * 2.0;
    vec2 m = iMouse.xy/R.xy - 0.5;
    if (iMouse.z <= 0.0) {
        float s = sin(4.5 * iTime);
        vec2 t = vec2(1.0, 1.2) * (iTime - 0.25 * s);
        vec2 a = 0.5 * sin(t);
        float s2 = sin(iTime * 3.0 + 0.1 * sin(iTime));
        vec2 b = vec2(sigmoid(4.*s2*s2*s2 + 2.*s2)*0.5, sin(t * 0.5) * 0.2);
        m = mix(a, b, clamp(-4.0 + 10.0 * sin(0.5 * iTime), 0.0, 1.0));
    }
    else {
        m.y += sqr(sqr(sin(iTime)))*.07;
    }
    O = vec4(face(uv * 1.3-vec2(0,0.2), m), 1.0);
}
